style.css:
@-moz-document domain("youtube.com") {
:root {
        --bg-geral: url("https://images2.imgbox.com/39/3a/21dfb871_o.jpg");
        --bg-video: url("https://images2.imgbox.com/8f/c9/8eebb10e_o.jpg");
        --logo-chibi: url("https://images2.imgbox.com/b5/02/4a12351c_o.jpg");
    }

    html, body, ytd-app, #page-manager, ytd-browse, ytd-watch-flexy,
    #columns, #primary, #secondary, #content, #contents,
    ytd-two-column-browse-results-renderer {
        background-color: transparent !important;
        background-image: none !important;
        --yt-spec-base-background: transparent !important;
        --yt-spec-general-background-a: transparent !important;
        --yt-spec-general-background-b: transparent !important;
        --yt-spec-general-background-c: transparent !important;
        --yt-spec-brand-background-primary: transparent !important;
        --yt-spec-brand-background-solid: transparent !important;
        --yt-spec-raised-background: transparent !important;
        --yt-main-app-background: transparent !important;
    }

    /* Fundo padrão (Feed - Notas Musicais) */
    html {
        background-image: var(--bg-geral) !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* ✅ CORREÇÃO PRINCIPAL: detecta página de vídeo pelo elemento ytd-watch-flexy */
    ytd-watch-flexy {
        background-image: none !important;
    }

    body:has(ytd-watch-flexy) {
        background-image: none !important;
    }

    html:has(ytd-watch-flexy) {
        background-image: var(--bg-video) !important;
    }

    /* Logo Chibi */
    ytd-topbar-logo-renderer svg, #logo-icon {
        display: none !important;
    }

    ytd-topbar-logo-renderer a {
        width: 90px !important;
        height: 42px !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
    }

    ytd-topbar-logo-renderer a::after {
        content: "" !important;
        display: block !important;
        width: 90px !important;
        height: 42px !important;
        background-image: var(--logo-chibi) !important;
        background-size: contain !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* Tema Rosa */
    ytd-masthead {
        background: #E7A4C0 !important;
        border-bottom: 3px dashed #FFF0F5 !important;
    }

    ytd-searchbox #container {
        background: #FFF0F5 !important;
        border: 2px solid #E7A4C0 !important;
        border-radius: 25px !important;
    }

    ytd-searchbox #search-icon-legacy {
        background: #E7A4C0 !important;
        border-radius: 0 25px 25px 0 !important;
    }

    ytd-rich-item-renderer, ytd-video-renderer, ytd-compact-video-renderer {
        background: rgba(255, 255, 255, 0.75) !important;
        border: 2px dashed #E7A4C0 !important;
        border-radius: 15px !important;
        backdrop-filter: blur(4px) !important;
        padding: 10px !important;
    }

    yt-chip-cloud-chip-renderer {
        background: #FFF0F5 !important;
        border: 1px solid #E7A4C0 !important;
        border-radius: 20px !important;
    }

    yt-chip-cloud-chip-renderer[selected] {
        background: #E7A4C0 !important;
    }

    #video-title, #channel-name, #title, h1, h2, h3, span {
        color: #4A2E35 !important;
    }
}
